# ---------------------------------------------------------------- 5.1 metrics and log settings
WALK["az104-monitor-metrics-logs"] = walk(
    "Know what Azure collects for you automatically, and what you must switch on.",
    ["Metrics: numbers over time", "Reading charts: aggregation and granularity", "Activity log vs resource logs", "Diagnostic settings and destinations", "Guest OS data with Azure Monitor Agent"],
    [N("res", "Azure resource", 120, 220, "compute"), N("met", "Platform metrics", 380, 80, "service", "automatic, 93 days"), N("act", "Activity log", 380, 220, "service", "who did what, 90 days"),
     N("diag", "Diagnostic setting", 380, 360, "service", "you switch it on"), N("law", "Log Analytics", 650, 220, "service", "query with KQL"), N("stor", "Storage / Event Hubs", 650, 360, "storage"),
     N("ama", "Azure Monitor Agent", 120, 380, "service", "inside the VM")],
    [S("problem", "What happened?", "The app was slow last night. Why?",
       "To answer, you need data that was already being collected. Some of it Azure keeps automatically; some you must turn on beforehand.",
       add=["res"]),
     S("concept", "Metrics", "Metrics are collected automatically",
       "Every resource sends platform metrics (CPU, transactions, latency) every minute, kept for 93 days, free. View them in Metrics explorer.\n\nPick the aggregation carefully: Avg, Min, Max, Sum or Count, over a time granularity such as 1 minute or 1 hour. Split or filter by dimensions, for example by API name.",
       add=["met"], edges=[("res", "met")], learn=[0, 1], warn="A 1-hour average hides a 5-minute spike. Use Max and a small granularity to find spikes."),
     S("concept", "Logs", "Two kinds of logs",
       "The activity log records control-plane operations on the subscription: who created, changed or deleted what. Kept 90 days, free.\n\nResource logs record what happens inside a resource (for example every blob read). They are not collected until you create a diagnostic setting.",
       add=["act", "diag"], edges=[("res", "act"), ("res", "diag", "resource logs")], learn=[2]),
     S("technique", "Destinations", "Where a diagnostic setting sends data",
       "Send to a Log Analytics workspace (to query and alert), a storage account (cheap archive) or Event Hubs (to stream to other tools), or a partner solution. One resource can have several diagnostic settings.",
       add=["law", "stor"], edges=[("diag", "law"), ("diag", "stor")], learn=[3]),
     S("technique", "Guest OS", "Inside the VM: Azure Monitor Agent",
       "Platform metrics only see the VM from outside. For memory, disk space, Windows events or Syslog, install the Azure Monitor Agent and create a data collection rule (DCR) that says what to collect and where to send it. The old Log Analytics agent is retired.",
       add=["ama"], edges=[("ama", "law", "DCR")], learn=[4]),
     S("recap", "Recap", "Metrics and logs", "Metrics and activity log are free and automatic; the rest you switch on.",
       recap=["Platform metrics: automatic, 93 days", "Choose aggregation and granularity with care", "Activity log = who did what (90 days)",
              "Resource logs need a diagnostic setting", "Guest OS data: Azure Monitor Agent + DCR"])])

