# ---------------------------------------------------------------- 5.1 KQL
WALK["az104-kql"] = walk(
    "Ask questions of your logs with a few simple Kusto (KQL) commands.",
    ["Tables and the pipe", "Filtering with where and time", "Counting with summarize", "Choosing columns, sorting and charts"],
    [N("table", "Table", 120, 220, "service", "e.g. Heartbeat"), N("where", "where", 300, 220, "service", "filter rows"), N("sum", "summarize", 480, 220, "service", "count by"),
     N("out", "Result / chart", 680, 220, "user"), N("time", "ago(1h)", 300, 380, "service", "time filter"), N("proj", "project / sort", 480, 380, "service")],
    [S("problem", "Millions of rows", "Which VM stopped sending heartbeats?",
       "The data is in Log Analytics, but scrolling through millions of rows is impossible. KQL asks the question for you.",
       add=["table"]),
     S("concept", "Pipe", "Start with a table, then pipe",
       "A query starts with a table name, then passes rows through steps separated by |. Common tables: Heartbeat, Perf, Event, Syslog, AzureActivity, AzureDiagnostics, StorageBlobLogs.",
       add=["where", "out"], edges=[("table", "where", "|")], learn=[0]),
     S("technique", "where", "Filter rows",
       "where keeps rows that match: | where Computer == \"vm-web1\" and | where TimeGenerated > ago(1h). Use contains or has to search text. take 10 shows a few sample rows.",
       add=["time"], edges=[("time", "where")], learn=[1], tip="Always filter by time first; it makes queries faster and cheaper."),
     S("technique", "summarize", "Count and group",
       "summarize turns rows into totals: | summarize count() by Computer, or | summarize avg(CounterValue) by bin(TimeGenerated, 5m). bin() groups time into buckets.",
       add=["sum"], edges=[("where", "sum", "|"), ("sum", "out", "|")], learn=[2]),
     S("technique", "Shape", "Shape the output",
       "project chooses columns, extend adds calculated ones, sort by or top 10 by orders rows, and render timechart draws a chart.\n\nExample: Heartbeat | summarize LastSeen = max(TimeGenerated) by Computer | where LastSeen < ago(15m).",
       add=["proj"], edges=[("sum", "proj")], learn=[3]),
     S("recap", "Recap", "KQL", "Table | where | summarize | project | render.",
       recap=["Start with a table, chain with |", "where + ago() to filter", "summarize count() by ...; bin() for time buckets",
              "project, extend, sort, top", "render timechart for charts"])])

LAB["az104-kql"] = H(
    "Write KQL against Microsoft's free demo workspace", 30, "free", "Free. The demo workspace is provided by Microsoft with sample data; nothing is created in your subscription.",
    ["Signed in at portal.azure.com (any account).", "Open the Log Analytics demo: " + DEMO],
    [("In the demo, close the queries gallery. Type: Heartbeat | take 10  and select Run.", "Ten rows with Computer, OSType and TimeGenerated."),
     ("Run the query in the box.", "One row per computer with its heartbeat count.", None, "Heartbeat\n| where TimeGenerated > ago(1h)\n| summarize Beats = count() by Computer\n| sort by Beats desc"),
     ("Find machines that went quiet. Run the query in the box.", "Computers whose last heartbeat is older than 15 minutes (maybe none).", None, "Heartbeat\n| summarize LastSeen = max(TimeGenerated) by Computer\n| where LastSeen < ago(15m)"),
     ("Chart CPU. Run the query in the box.", "A line chart of CPU per computer.", None, "Perf\n| where TimeGenerated > ago(4h)\n| where ObjectName == \"Processor\" and CounterName == \"% Processor Time\"\n| summarize AvgCPU = avg(CounterValue) by bin(TimeGenerated, 15m), Computer\n| render timechart"),
     ("Top 5 events. Run the query in the box.", "The five most common Windows events.", None, "Event\n| where TimeGenerated > ago(1d)\n| summarize Count = count() by EventID, Source\n| top 5 by Count"),
     ("Pick any table on the left, expand it to see its columns, and write your own where + summarize query.", "Your own result.")],
    ["You wrote queries with where, summarize, bin, top and render."],
    ["Nothing to clean up."],
    [("Tutorial: use Kusto queries", ML + "kusto/query/tutorials/learn-common-operators"),
     ("Log Analytics tutorial", ML + "azure/azure-monitor/logs/log-analytics-tutorial"),
     ("Log Analytics demo environment", DEMO)])

# ---------------------------------------------------------------- 5.1 alerts
WALK["az104-alerts"] = walk(
    "Be told about problems before users notice, and silence alerts during planned work.",
    ["Alert rule: scope, condition, actions", "Signal types", "Action groups", "Alert processing rules", "Severity and state"],
    [N("res", "Resource", 110, 220, "compute"), N("rule", "Alert rule", 330, 220, "service", "CPU > 80% for 5 min"), N("alert", "Alert fired", 540, 220, "security", "Sev 2"),
     N("ag", "Action group", 720, 120, "service", "email, SMS, webhook"), N("apr", "Processing rule", 720, 340, "service", "suppress Sat 2-4am"), N("oncall", "On-call engineer", 540, 380, "user")],
    [S("problem", "Silence", "The site was down for two hours and nobody knew",
       "Charts are only useful if someone is looking. Alerts look for you.",
       add=["res"]),
     S("concept", "Rule", "An alert rule has three parts",
       "Scope (which resources), condition (signal + logic, such as Percentage CPU > 80 averaged over 5 minutes), and actions (an action group). Plus details: name and severity 0 (critical) to 4 (verbose).",
       add=["rule", "alert"], edges=[("res", "rule"), ("rule", "alert")], learn=[0, 4]),
     S("concept", "Signals", "What can trigger an alert",
       "Metrics, log search queries (KQL), activity log events (for example someone deleted a resource), resource health and service health.\n\nMetric alerts are stateful by default: they fire once and resolve when the condition clears.",
       learn=[1]),
     S("technique", "Action group", "Action groups say who and how",
       "An action group is reusable: notifications (email, SMS, push, voice) and actions (webhook, Logic App, Azure Function, Automation runbook, ITSM, Event Hub). Many rules can share one group.",
       add=["ag", "oncall"], edges=[("alert", "ag"), ("ag", "oncall", "email + SMS")], learn=[2]),
     S("technique", "Processing", "Alert processing rules change alerts at scale",
       "Alert processing rules apply to fired alerts across a scope: suppress notifications during maintenance windows, or add an action group to all alerts in a subscription. The alerts still fire and are recorded.",
       add=["apr"], edges=[("apr", "ag", "suppress")], learn=[3], warn="Suppressed alerts still appear in the portal; only their actions are paused."),
     S("recap", "Recap", "Alerts", "Rule → alert → action group, adjusted by processing rules.",
       recap=["Scope + condition + action group", "Signals: metric, log, activity log, health", "Action groups are reusable",
              "Processing rules suppress or add actions at scale", "Severity 0 (critical) to 4"])])

