WALK["az104-backup-vaults"] = walk(
    "Choose the right vault for what you back up, and set it up safely before the first backup.",
    ["Recovery Services vault: what it protects", "Backup vault: what it protects", "Region and storage redundancy settings", "Soft delete and other security features"],
    [N("rsv", "Recovery Services vault", 220, 120, "security"), N("bv", "Backup vault", 580, 120, "security"), N("vm", "Azure VMs", 100, 290, "compute"),
     N("files", "Azure Files", 260, 290, "storage"), N("sql", "SQL in VM", 100, 400, "database"), N("disk", "Managed disks", 480, 290, "storage"),
     N("blob", "Blobs", 640, 290, "storage"), N("pg", "PostgreSQL", 560, 400, "database")],
    [S("problem", "Where do backups go?", "You need backups, but which vault?",
       "Azure Backup stores recovery points in a vault. There are two vault types, and each protects different things.",
       add=["rsv", "bv"]),
     S("concept", "RSV", "Recovery Services vault",
       "Protects Azure VMs, SQL Server and SAP HANA in VMs, Azure Files, on-premises machines (MARS agent, MABS) and is also used by Azure Site Recovery.",
       add=["vm", "files", "sql"], edges=[("rsv", "vm"), ("rsv", "files"), ("rsv", "sql")], learn=[0]),
     S("concept", "Backup vault", "Backup vault",
       "The newer vault type for Azure Disks, Azure Blobs, Azure Database for PostgreSQL, AKS and similar workloads.",
       add=["disk", "blob", "pg"], edges=[("bv", "disk"), ("bv", "blob"), ("bv", "pg")], learn=[1], warn="Backing up managed disks directly (not the whole VM) uses a Backup vault."),
     S("technique", "Settings", "Decide before the first backup",
       "Create the vault in the same region as the resources it protects. Backup storage redundancy (GRS by default, or LRS / ZRS) can only be changed before you protect the first item. Enable cross-region restore if you need to restore in the paired region.",
       learn=[2]),
     S("technique", "Security", "Protect the backups themselves",
       "Soft delete keeps deleted backup data for 14 days (or longer). Immutability prevents early deletion of recovery points. Multi-user authorization needs a second person's approval for critical operations.",
       learn=[3]),
     S("recap", "Recap", "Vaults", "Right vault, right region, settings first.",
       recap=["RSV: VMs, SQL/SAP HANA in VMs, Azure Files, on-premises, Site Recovery", "Backup vault: disks, blobs, PostgreSQL, AKS", "Same region as the protected resources",
              "Set storage redundancy before the first backup", "Soft delete, immutability, multi-user authorization"])])

